package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.TemporalPasswordVO;

class TemporalPasswordValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of temporal password of user")
  void test_temporal_password_value_holder_assign_plain_value() {
    Object holder = new Object();
    TemporalPasswordValueHolder<Object> value = new TemporalPasswordValueHolder<>(holder);
    Assertions.assertSame(holder, value.temporalPassword(true), "Setters must return the holder");
    Assertions.assertTrue(value.getTemporalPasswordValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getTemporalPassword().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.temporalPasswordNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTemporalPasswordValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of temporal password of user")
  void test_temporal_password_value_holder_assign_value_object() {
    Object holder = new Object();
    TemporalPasswordValueHolder<Object> value = new TemporalPasswordValueHolder<>(holder);
    TemporalPasswordVO vo = TemporalPasswordVO.from(true);
    Assertions.assertFalse(value.getTemporalPasswordValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.temporalPassword(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTemporalPasswordValue().orElseThrow());
    Assertions.assertSame(holder, value.temporalPassword(Optional.empty()));
    Assertions.assertFalse(value.getTemporalPasswordValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.temporalPassword(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTemporalPasswordValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of temporal password of user against the original")
  void test_temporal_password_value_holder_read() {
    Object holder = new Object();
    TemporalPasswordValueHolder<Object> value = new TemporalPasswordValueHolder<>(holder);
    TemporalPasswordVO vo = TemporalPasswordVO.from(true);
    TemporalPasswordVO other = TemporalPasswordVO.from(true);
    User original = Mockito.mock(User.class);
    Mockito.when(original.getTemporalPasswordValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTemporalPassword(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTemporalPassword(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.temporalPassword(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTemporalPassword(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTemporalPassword(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of temporal password of user")
  void test_temporal_password_value_holder_unset() {
    Object holder = new Object();
    TemporalPasswordValueHolder<Object> value = new TemporalPasswordValueHolder<>(holder);
    TemporalPasswordVO vo = TemporalPasswordVO.from(true);
    value.temporalPassword(vo);
    Assertions.assertSame(holder, value.unsetTemporalPasswordIfMatches("temporalPassword_other"));
    Assertions.assertTrue(value.getTemporalPasswordValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTemporalPasswordIfMatches("temporalPassword"));
    Assertions.assertFalse(value.getTemporalPasswordValue().isPresent(),
        "The field name must clear the value");
    value.temporalPassword(vo);
    Assertions.assertSame(holder, value.unsetTemporalPassword());
    Assertions.assertFalse(value.getTemporalPasswordValue().isPresent(),
        "Unset must clear the value");
  }
}
